const { body, jwtPayload: token, rawmatSha256 } = $input.first().json;
const now = Math.floor(Date.now() / 1000);
const eventId = /^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/;
if (!token || token.iss !== 'rawmat' || token.aud !== 'rawmat-notifications' ||
    !Number.isInteger(token.iat) || token.iat > now + 30 || token.exp !== token.iat + 300 ||
    token.exp <= now || !eventId.test(token.jti ?? '') || token.sha256 !== rawmatSha256 ||
    !body || body.id !== token.jti || typeof body.message !== 'string' ||
    body.message.length === 0 || body.message.length > 1024 ||
    !Array.isArray(body.recipients) || body.recipients.length === 0 || body.recipients.length > 40 ||
    body.recipients.some((number) => typeof number !== 'string' || !/^\+[1-9][0-9]{6,14}$/.test(number)) ||
    new Set(body.recipients).size !== body.recipients.length) {
  throw new Error('Invalid Rawmat notification');
}
return body.recipients.map((recipient) => ({ json: { id: body.id, recipient, message: body.message } }));

const requests = $('Validate and split').all();
const responses = $input.all();
const hasProviderId = ({ json }) =>
  [json.messages?.[0]?.id, json.sid].some((id) => typeof id === 'string' && id.length > 0);
if (!requests.length || responses.length !== requests.length || !responses.every(hasProviderId)) {
  throw new Error('Message provider did not confirm every recipient');
}
return [{ json: { id: requests[0].json.id, accepted: true } }];
